steps.script:
var fd = tree.root.get_node_or_null("/root/Main/FormationsDialog")
if fd == null or not fd.visible:
	return "no dialog"
var vp = tree.root.get_visible_rect().size
var expected_x = (vp.x - float(fd.size.x)) * 0.5
if absf(float(fd.position.x) - expected_x) > 4.0:
	return "dialog at %d, not centred for viewport %s (expected %.0f) - it popped before the rescale" % [fd.position.x, str(vp), expected_x]
return "centred"

var ov = tree.root.get_node("/root/TutorialOverlay")
var fd = tree.root.get_node("/root/Main/FormationsDialog")
var card = ov.card_rect()
var dlg = Rect2(Vector2(fd.position), Vector2(fd.size))
if card.intersects(dlg):
	return "card %s runs under dialog %s" % [str(card), str(dlg)]
return "clear"

var ov = tree.root.get_node("/root/TutorialOverlay")
var card = ov.card_rect()
var vp = tree.root.get_visible_rect().size
if card.position.x < -0.5 or card.position.y < -0.5 or card.end.x > vp.x + 0.5 or card.end.y > vp.y + 0.5:
	return "card %s off-screen in viewport %s" % [str(card), str(vp)]
return "onscreen"

var ov = tree.root.get_node("/root/TutorialOverlay")
var footer = ov.get_node("InstructorCard/Margin/VBox/Footer")
var card = ov.card_rect()
if footer.get_combined_minimum_size().x > card.size.x:
	return "footer needs %.0fpx, card is %.0fpx" % [footer.get_combined_minimum_size().x, card.size.x]
return "fits"

var b = tree.root.get_node("/root/TutorialOverlay/InstructorCard/Margin/VBox/Footer/SkipStepButton")
var fd = tree.root.get_node("/root/Main/FormationsDialog")
if not b.is_visible_in_tree():
	return "Skip Step hidden"
if b.get_global_rect().intersects(Rect2(Vector2(fd.position), Vector2(fd.size))):
	return "Skip Step behind the dialog"
return "clickable"
